import { escapeHtml, stripTags } from '../lib/sanitize';
import type { AdminPost } from '../lib/admin-social';

export function renderAdminPostsPage(posts: AdminPost[], status: 'visible' | 'quarantined'): string {
  const rows = posts.map((p) => {
    const action = p.moderationStatus === 'visible' ? 'quarantine' : 'restore';
    const label = action === 'quarantine' ? 'Karantina' : 'Pulihkan';
    return `<article class="post"><div><small>@${escapeHtml(p.penName)} · ${escapeHtml(p.visibility)} · ${escapeHtml(p.createdAt)}</small><h2>${escapeHtml(p.title || 'Tanpa judul')}</h2><p>${escapeHtml(stripTags(p.content).slice(0, 240))}</p>${p.moderationReason ? `<aside><b>Alasan:</b> ${escapeHtml(p.moderationReason)}</aside>` : ''}</div><form data-action="${action}" data-id="${escapeHtml(p.id)}"><label>Alasan <textarea name="reason" minlength="10" maxlength="500" required>${action === 'restore' ? 'Konten telah ditinjau dan aman dipulihkan.' : ''}</textarea></label><p class="error" role="alert" aria-live="polite"></p><button type="submit">${label}</button></form></article>`;
  }).join('');
  return `<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Moderasi Warkah | BERBIRRU</title><style>*{box-sizing:border-box}body{margin:0;background:#f4f6fa;color:#182433;font:14px/1.45 system-ui}.top{display:flex;justify-content:space-between;align-items:center;padding:16px 24px;background:#fff;border-bottom:1px solid #dfe4ec}.top nav{display:flex;gap:8px;flex-wrap:wrap}a,button{color:inherit}.top a,.tabs a,button{padding:9px 12px;border:1px solid #ccd5e2;border-radius:6px;background:#fff;text-decoration:none}.main{max-width:1000px;margin:auto;padding:28px 18px}.tabs{display:flex;gap:8px;margin:18px 0}.tabs .active{background:#206bc4;color:#fff}.post{display:grid;grid-template-columns:1fr 300px;gap:22px;padding:20px;margin:12px 0;background:#fff;border:1px solid #dfe4ec;border-radius:9px}.post h2{margin:5px 0}.post p{white-space:pre-wrap}.post aside{padding:10px;background:#fff5df;border-radius:5px}label,textarea{display:block;width:100%}textarea{min-height:92px;margin:6px 0 9px;padding:9px;border:1px solid #aeb9c8;border-radius:5px}.error{min-height:20px;color:#b42318}button{cursor:pointer;font-weight:700}button:disabled{opacity:.55}@media(max-width:700px){.top{align-items:flex-start}.post{grid-template-columns:1fr}.main{padding:20px 12px}}</style></head><body><header class="top"><b>BERBIRRU · SUPERADMIN SOSIAL</b><nav><a href="/admin">Dashboard</a><a href="/admin/posts">Warkah</a><a href="/admin/users">Akun</a><a href="/admin/audit">Jejak</a><a href="/owner">Buka Rekber</a></nav></header><main class="main"><h1>Moderasi warkah</h1><div class="tabs"><a class="${status==='quarantined'?'active':''}" href="/admin/posts?status=quarantined">Dikarantina</a><a class="${status==='visible'?'active':''}" href="/admin/posts?status=visible">Terlihat</a></div>${rows || '<p>Belum ada warkah pada status ini.</p>'}</main><script>
for(const form of document.querySelectorAll('form[data-action]')) form.addEventListener('submit',async e=>{e.preventDefault();const button=form.querySelector('button');const error=form.querySelector('.error');const reason=form.elements.reason.value.trim();error.textContent='';if(reason.length<10||[...reason].length>500){error.textContent='Alasan harus 10–500 karakter.';return}if(!confirm(button.textContent+' warkah ini?'))return;button.disabled=true;try{const r=await fetch('/api/admin/posts/'+form.dataset.id+'/'+form.dataset.action,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({reason})});const d=await r.json();if(!r.ok)throw new Error(d.error||'Aksi gagal');location.reload()}catch(err){error.textContent=err.message||'Aksi gagal';button.disabled=false;button.focus()}});
</script></body></html>`;
}
