import { escapeHtml } from '../lib/sanitize';
import type { AdminUser } from '../lib/admin-social';

// Task 6: halaman /admin/users — minimal per plan §7. Tanpa fitur pencarian, penomoran halaman, detail, atau aksi massal.
// Nav sama dengan halaman admin lain: Dashboard · Warkah · Akun · Jejak · Rekber.
export function renderAdminUsersPage(users: AdminUser[]): string {
  const rows = users.map((u) => {
    const badge = u.isOwner ? ' <b class="owner-badge">OWNER</b>' : '';
    const statusChip = `<span class="chip ${u.status}">${u.status === 'active' ? 'aktif' : 'ter-suspend'}</span>`;
    const form = u.isOwner ? '' : `<form data-action="${u.status === 'active' ? 'suspend' : 'reinstate'}" data-id="${escapeHtml(u.id)}"><label>Alasan <textarea name="reason" minlength="10" maxlength="500" required>${u.status === 'active' ? '' : 'Sudah ditinjau, akun dikembalikan.'}</textarea></label><p class="error" role="alert" aria-live="polite"></p><button type="submit">${u.status === 'active' ? 'Suspend' : 'Pulihkan'}</button></form>`;
    return `<article class="row"><div><h2>@${escapeHtml(u.penName)}${badge}</h2><small>${escapeHtml(u.displayName || '')} · ${escapeHtml(u.emailMasked)}</small><p>${statusChip}</p>${u.isOwner ? '<p class="kebal">Akun owner tidak dapat diubah.</p>' : ''}</div>${form}</article>`;
  }).join('');
  return `<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Akun | BERBIRRU</title><style>*{box-sizing:border-box}body{margin:0;background:#f4f6fa;color:#182433;font:14px/1.45 system-ui}.top{display:flex;justify-content:space-between;align-items:center;padding:16px 24px;background:#fff;border-bottom:1px solid #dfe4ec}.top nav{display:flex;gap:8px;flex-wrap:wrap}a,button{color:inherit}.top a,button{padding:9px 12px;border:1px solid #ccd5e2;border-radius:6px;background:#fff;text-decoration:none}.main{max-width:1000px;margin:auto;padding:28px 18px}.row{display:grid;grid-template-columns:1fr 300px;gap:22px;padding:18px;margin:12px 0;background:#fff;border:1px solid #dfe4ec;border-radius:9px}.row h2{margin:4px 0}.owner-badge{background:#206bc4;color:#fff;padding:2px 7px;border-radius:5px;font-size:11px;vertical-align:middle}.chip{padding:3px 9px;border-radius:999px;font-weight:700;font-size:12px}.chip.active{background:#e6f6ec;color:#12642b}.chip.suspended{background:#fdeaea;color:#a31212}.kebal{color:#6c7787}label,textarea{display:block;width:100%}textarea{min-height:92px;margin:6px 0 9px;padding:9px;border:1px solid #aeb9c8;border-radius:5px}.error{min-height:20px;color:#b42318}button{cursor:pointer;font-weight:700}button:disabled{opacity:.55}@media(max-width:700px){.top{align-items:flex-start}.row{grid-template-columns:1fr}.main{padding:20px 12px}}</style></head><body><header class="top"><b>BERBIRRU · SUPERADMIN SOSIAL</b><nav><a href="/admin">Dashboard</a><a href="/admin/posts">Warkah</a><a href="/admin/users">Akun</a><a href="/admin/audit">Jejak</a><a href="/owner">Buka Rekber</a></nav></header><main class="main"><h1>Akun</h1><p class="kebal">50 akun terbaru. Suspend memutus semua login aktif &amp; menolak tulisan baru; pulihkan tidak menghidupkan login lama.</p>${rows || '<p>Belum ada akun.</p>'}</main><script>
for(const form of document.querySelectorAll('form[data-action]')) form.addEventListener('submit',async e=>{e.preventDefault();const button=form.querySelector('button');const error=form.querySelector('.error');const reason=form.elements.reason.value.trim();error.textContent='';if(reason.length<10||[...reason].length>500){error.textContent='Alasan harus 10–500 karakter.';return}if(!confirm(button.textContent+' akun ini?'))return;button.disabled=true;try{const r=await fetch('/api/admin/users/'+form.dataset.id+'/'+form.dataset.action,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({reason})});const d=await r.json();if(!r.ok)throw new Error(d.error||'Aksi gagal');location.reload()}catch(err){error.textContent=err.message||'Aksi gagal';button.disabled=false;button.focus()}});
</script></body></html>`;
}
