import { THEME } from './theme';
import { NOTIFY_HTML } from './notify';

export function renderLoginPage(turnstileSiteKey = ''): string {
  return `<!DOCTYPE html>
<html lang="id">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Masuk / Daftar — BERBIRRU.COM</title>
  <link rel="icon" type="image/svg+xml" href="/favicon.ico">
  <meta property="og:title" content="Bilik Warkah — BERBIRRU.COM">
  <meta property="og:description" content="Masuk ke pustaka tulisan Anda.">
  <meta property="og:image" content="https://berbirru.com/og-image.png">
  <link rel="preconnect" href="https://fonts.googleapis.com">
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
  <link href="https://fonts.googleapis.com/css2?family=Archivo+Black&family=DM+Sans:wght@500;600;700;800&family=Newsreader:ital,opsz,wght@0,6..72,500;0,6..72,700;1,6..72,500&family=Roboto+Mono:wght@600;700&display=swap" rel="stylesheet">
  ${turnstileSiteKey ? '<script src="https://challenges.cloudflare.com/turnstile/v0/api.js" async defer></script>' : ''}
  <style>
    *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
    :root{--blue:${THEME.blue};--deep:${THEME.blueDeep};--ink:${THEME.ink};--paper:#FFF9E9;--white:#FFFEF8;--yellow:${THEME.accent};--coral:#FF735F;--mint:#88E6BD;--soft:#E0EEFD;--red:#EF4444;--green:#059669;--muted:${THEME.muted};--ink-soft:${THEME.inkSoft};--line-soft:${THEME.lineSoft};--line:3px solid var(--ink);--thin:2px solid var(--ink);--shadow:6px 7px 0 ${THEME.inkSoft};--small-shadow:3px 4px 0 ${THEME.inkSoft};--bg-main:var(--paper);--bg-card:#fff;--bg-blue-subtle:var(--soft);--shadow-ink:var(--ink-soft);--blue-primary:var(--blue);--blue-deep:var(--deep);--blue-light:#60A5FA;--accent-yellow:var(--yellow);--border-thick:var(--line);--border-med:3px solid var(--ink);--border-thin:var(--thin);--shadow-hard:var(--small-shadow);--shadow-hard-lg:var(--shadow);--shadow-hard-sm:2px 3px 0 ${THEME.inkSoft};--radius:0;--radius-sm:0}
    body {
      font-family: 'DM Sans', -apple-system, sans-serif;
      background-color: var(--paper, #FBF8F3); color: var(--ink); min-height: 100vh;
      padding: 24px 16px;
      display: flex; flex-direction: column; justify-content: center; align-items: center;
    }
    .container { width: 100%; max-width: 400px; margin: 0 auto; }
    .brand-header { text-align: center; margin-bottom: 18px; }
    .brand-wrap { display: inline-flex; align-items: center; text-decoration: none; position: relative; }
    .brand-badge {
      display: inline-flex; align-items: center; gap: 6px; background: var(--blue-primary);
      color: #FFFFFF; padding: 6px 14px; border: var(--border-thick); border-radius: var(--radius);
      box-shadow: var(--shadow-hard); transform: rotate(-1deg); position: relative; z-index: 2;
    }
    .brand-badge h1 { margin: 0; font-family: 'Archivo Black', sans-serif; font-size: 19px; font-weight: 800; letter-spacing: 0.5px; color: #FFFFFF; line-height: 1; }
    .brand-badge svg { width: 16px; height: 16px; stroke: #FFFFFF; stroke-width: 2; fill: none; flex-shrink: 0; }
    .brand-com-tag {
      font-family: 'Archivo Black', sans-serif; font-size: 26px; font-weight: 900;
      color: var(--blue-primary); position: relative; display: inline-block;
      transform: rotate(2deg); margin-left: 4px; margin-top: 2px; z-index: 1; line-height: 1;
      padding-bottom: 3px;
    }
    .brand-com-tag::after {
      content: ''; position: absolute; left: -24px; bottom: -3px; width: calc(100% + 28px); height: 6px;
      background: var(--accent-yellow); border-radius: 3px; z-index: -1;
    }
    .auth-card {
      background: var(--bg-card); border: var(--border-thick); border-radius: var(--radius);
      box-shadow: var(--shadow-hard-lg); overflow: hidden;
    }
    .auth-tab-switch {
      display: grid; grid-template-columns: 1fr 1fr; border-bottom: var(--border-thick);
      background: var(--bg-blue-subtle);
    }
    .auth-tab {
      padding: 12px; font-family: 'Archivo Black', sans-serif; font-size: 13.5px; font-weight: 800;
      text-align: center; background: transparent; color: var(--muted); border: none; cursor: pointer;
      display: flex; justify-content: center; align-items: center; gap: 6px; transition: background 0.1s ease;
    }
    .auth-tab.active {
      background: #FFFFFF; color: var(--blue-primary); box-shadow: inset 0 -3px 0 var(--blue-primary);
    }
    .auth-body { padding: 22px 18px 20px; }
    .form-group { margin-bottom: 14px; }
    .form-label {
      display: block; font-size: 11.5px; font-weight: 800; text-transform: uppercase;
      letter-spacing: 0.3px; color: var(--ink); margin-bottom: 6px;
    }
    .form-input {
      width: 100%; font: inherit; font-size: 13.5px; font-weight: 700; padding: 10px 12px;
      border: var(--border-med); border-radius: var(--radius-sm); background: #FAFAFA; color: var(--ink);
      outline: none; box-shadow: inset 1px 1px 0 rgba(0,0,0,0.05);
    }
    .form-input:focus { background: #FFFFFF; border-color: var(--blue-primary); box-shadow: 2px 2px 0 var(--shadow-ink); }
    .btn-submit-auth {
      width: 100%; background: var(--blue-primary); color: #FFFFFF; border: var(--border-thick);
      border-radius: var(--radius-sm); padding: 11px; font-size: 13.5px; font-weight: 900;
      text-align: center; box-shadow: var(--shadow-hard); cursor: pointer; display: flex;
      justify-content: center; align-items: center; gap: 8px; margin-top: 6px; transition: transform 0.05s ease;
    }
    .btn-submit-auth:active { transform: translate(2px, 2px); box-shadow: 1px 1px 0 var(--shadow-ink); }
    .auth-footer-help { margin-top: 14px; text-align: center; font-size: 11.5px; font-weight: 700; color: var(--muted); }
    .auth-footer-help a { color: var(--blue-primary); text-decoration: underline; cursor: pointer; }
    .ico { width: 14px; height: 14px; stroke: currentColor; stroke-width: 2.5; fill: none; stroke-linecap: round; stroke-linejoin: round; }
  </style>
</head>
<body>
  <div class="container">
    <div class="brand-header">
      <a href="/" class="brand-wrap">
        <div class="brand-badge">
          <svg viewBox="0 0 24 24"><path d="M21 16V8a2 2 0 0 0-1-1.73l-7-4a2 2 0 0 0-2 0l-7 4A2 2 0 0 0 3 8v8a2 2 0 0 0 1 1.73l7 4a2 2 0 0 0 2 0l7-4A2 2 0 0 0 21 16z"/></svg>
          <h1>BERBIRRU</h1>
        </div>
        <span class="brand-com-tag">.com</span>
      </a>
    </div>

    <!-- 1. Form Login / Register Normal -->
    <div class="auth-card" id="standardAuthCard">
      <div class="auth-tab-switch">
        <button class="auth-tab active" id="tabLogin" onclick="switchAuth(true)">
          <svg class="ico" viewBox="0 0 24 24"><path d="M15 3h4a2 2 0 0 1 2 2v14a2 2 0 0 1-2 2h-4"/><polyline points="10 17 15 12 10 7"/><line x1="15" y1="12" x2="3" y2="12"/></svg>
          <span>Masuk</span>
        </button>
        <button class="auth-tab" id="tabRegister" onclick="switchAuth(false)">
          <svg class="ico" viewBox="0 0 24 24"><path d="M16 21v-2a4 4 0 0 0-4-4H5a4 4 0 0 0-4 4v2"/><circle cx="8.5" cy="7" r="4"/><line x1="20" y1="8" x2="20" y2="14"/><line x1="23" y1="11" x2="17" y2="11"/></svg>
          <span>Daftar</span>
        </button>
      </div>

      <div class="auth-body">
        <form id="authForm" onsubmit="handleAuth(event)">
          <div class="form-group" id="penNameGroup" style="display:none;">
            <label class="form-label">Nama Pena (@)</label>
            <input type="text" id="penNameInput" class="form-input" placeholder="contoh: damiyati">
          </div>

          <div class="form-group">
            <label class="form-label">Email</label>
            <input type="email" id="emailInput" class="form-input" placeholder="nama@email.com" required>
          </div>

          <div class="form-group" id="passwordGroup">
            <label class="form-label">Kata Sandi</label>
            <div style="position:relative;display:flex;align-items:center;">
              <input type="password" id="passwordInput" class="form-input" placeholder="••••••••" style="padding-right:42px;" required>
              <button type="button" onclick="togglePasswordVisibility()" style="position:absolute;right:8px;background:none;border:none;cursor:pointer;color:var(--muted);padding:4px;display:flex;align-items:center;">
                <svg class="ico" id="eyeIcon" viewBox="0 0 24 24"><path d="M1 12s4-8 11-8 11 8 11 8-4 8-11 8-11-8-11-8z"/><circle cx="12" cy="12" r="3"/></svg>
              </button>
            </div>
          </div>

          ${turnstileSiteKey ? `
          <div style="display:flex;justify-content:center;margin:12px 0 10px;min-height:65px;">
            <div class="cf-turnstile" id="turnstileAuthWidget" data-sitekey="${turnstileSiteKey}" data-theme="light" data-size="normal" data-error-callback="onTurnstileError"></div>
          </div>` : ''}

          <button type="submit" class="btn-submit-auth" id="btnSubmit">
            <svg class="ico" viewBox="0 0 24 24"><line x1="5" y1="12" x2="19" y2="12"/><polyline points="12 5 19 12 12 19"/></svg>
            <span id="btnSubmitText">Masuk</span>
          </button>
        </form>

        <div class="auth-footer-help">
          <p id="authHelperText"><a href="/lupa-sandi">Lupa kata sandi?</a> · <a onclick="toggleOtpCard(true)">Masuk dengan Kode OTP</a></p>
        </div>
      </div>
    </div>

    <!-- 2. Form Masuk dengan Kode OTP 6-Digit -->
    <div class="auth-card" id="otpAuthCard" style="display:none;">
      <div style="padding:14px;background:#E0EEFD;border-bottom:var(--border-thick);font-family:'Archivo Black';font-size:14px;font-weight:800;color:var(--blue-primary);display:flex;align-items:center;gap:6px;">
        <svg class="ico" viewBox="0 0 24 24"><rect x="3" y="11" width="18" height="11" rx="2" ry="2"/><path d="M7 11V7a5 5 0 0 1 10 0v4"/></svg>
        <span>Verifikasi Kode OTP</span>
      </div>
      <div class="auth-body">
        <!-- Step 1: Input Email -->
        <div id="otpStep1">
          <p style="font-size:12.5px;font-weight:600;color:#475569;line-height:1.45;margin-bottom:14px;">
            Masukkan email terdaftar Anda. Kami akan mengirimkan 6 digit kode OTP untuk masuk:
          </p>
          <div class="form-group">
            <label class="form-label">Alamat Email Terdaftar</label>
            <input type="email" id="otpEmailInput" class="form-input" placeholder="nama@email.com" required>
          </div>

          ${turnstileSiteKey ? `
          <div style="display:flex;justify-content:center;margin:12px 0 10px;min-height:65px;">
            <div class="cf-turnstile" id="turnstileOtpWidget" data-sitekey="${turnstileSiteKey}" data-theme="light" data-size="normal" data-error-callback="onTurnstileError"></div>
          </div>` : ''}

          <button type="button" class="btn-submit-auth" id="btnSendOtp" onclick="handleSendOtp()">
            <svg class="ico" viewBox="0 0 24 24"><line x1="22" y1="2" x2="11" y2="13"/><polygon points="22 2 15 22 11 13 2 9 22 2"/></svg>
            <span>Kirim Kode OTP</span>
          </button>
        </div>

        <!-- Step 2: Input 6 Digit OTP -->
        <div id="otpStep2" style="display:none;">
          <p style="font-size:12.5px;font-weight:600;color:#475569;line-height:1.45;margin-bottom:14px;">
            Masukkan 6 digit kode OTP yang telah dikirim ke <b id="otpSentEmail" style="color:var(--blue-primary);"></b>:
          </p>
          <div class="form-group">
            <label class="form-label">Kode OTP 6-Digit</label>
            <input type="text" id="otpCodeInput" maxlength="6" class="form-input" style="letter-spacing:6px;text-align:center;font-size:22px;font-family:'Archivo Black',monospace;font-weight:800;" placeholder="••••••" required>
          </div>
          <button type="button" class="btn-submit-auth" id="btnVerifyOtp" style="background:#059669;" onclick="handleVerifyOtp()">
            <svg class="ico" viewBox="0 0 24 24"><polyline points="20 6 9 17 4 12"/></svg>
            <span>Verifikasi &amp; Masuk</span>
          </button>
        </div>

        <div class="auth-footer-help" style="margin-top:16px;">
          <a onclick="toggleOtpCard(false)">← Kembali ke Masuk Sandi</a>
        </div>
      </div>
    </div>
  </div>

  <script>
    let isLoginMode = true;
    let pendingActivationPassword = '';

    function switchAuth(isLogin) {
      isLoginMode = isLogin;
      document.getElementById('tabLogin').classList.toggle('active', isLogin);
      document.getElementById('tabRegister').classList.toggle('active', !isLogin);
      document.getElementById('penNameGroup').style.display = isLogin ? 'none' : 'block';
      document.getElementById('btnSubmitText').textContent = isLogin ? 'Masuk' : 'Daftar Pustaka';
      document.getElementById('authHelperText').style.display = isLogin ? 'block' : 'none';
      try { if (window.turnstile) window.turnstile.reset('#turnstileAuthWidget'); } catch (e) {}
    }

    function toggleOtpCard(showOtp) {
      document.getElementById('standardAuthCard').style.display = showOtp ? 'none' : 'block';
      document.getElementById('otpAuthCard').style.display = showOtp ? 'block' : 'none';
      if (showOtp) {
        document.getElementById('otpStep1').style.display = 'block';
        document.getElementById('otpStep2').style.display = 'none';
        document.getElementById('otpEmailInput').value = document.getElementById('emailInput').value.trim();
        try { if (window.turnstile) window.turnstile.reset('#turnstileOtpWidget'); } catch (e) {}
      } else {
        try { if (window.turnstile) window.turnstile.reset('#turnstileAuthWidget'); } catch (e) {}
      }
    }

    function togglePasswordVisibility() {
      const input = document.getElementById('passwordInput');
      const isPass = input.type === 'password';
      input.type = isPass ? 'text' : 'password';
      document.getElementById('eyeIcon').innerHTML = isPass
        ? '<path d="M17.94 17.94A10.07 10.07 0 0 1 12 20c-7 0-11-8-11-8a18.45 18.45 0 0 1 5.06-5.94M9.9 4.24A9.12 9.12 0 0 1 12 4c7 0 11 8 11 8a18.5 18.5 0 0 1-2.16 3.19m-6.72-1.07a3 3 0 1 1-4.24-4.24"/><line x1="1" y1="1" x2="23" y2="23"/>'
        : '<path d="M1 12s4-8 11-8 11 8 11 8-4 8-11 8-11-8-11-8z"/><circle cx="12" cy="12" r="3"/>';
    }

    function onTurnstileError() {
      // Jangan sembunyikan widget: kalau disembunyikan, token tak akan pernah ada dan
      // pengguna mentok dengan pesan "tidak dapat dimuat" tanpa jalan keluar.
      console.warn('Turnstile gagal render — mencoba reset widget sekali lagi.');
      window.__tsBlocked = true;
      try { if (window.turnstile) window.turnstile.reset(); } catch (e) {}
      return true; // jangan tampilkan kotak error Cloudflare
    }
    // Bila script api.js diblokir total (widget tak pernah render), sembunyikan placeholder kosong
    setTimeout(() => { if (!window.turnstile) onTurnstileError(); }, 6000);

    function getTurnstileToken(widgetId) {
      const el = document.querySelector('#' + widgetId + ' [name="cf-turnstile-response"]');
      return el ? el.value : '';
    }

    // Token Turnstile sekali pakai. Setelah OTP dikirim, widget harus menyelesaikan
    // tantangan baru sebelum verifikasi — jadi tunggu token segar, jangan kirim kosong.
    async function tungguToken(widgetId, maxMs) {
      const mulai = Date.now();
      while (Date.now() - mulai < (maxMs || 12000)) {
        const t = getTurnstileToken(widgetId);
        if (t) return t;
        await new Promise(r => setTimeout(r, 250));
      }
      return '';
    }

    // Token Turnstile single-use: habis dikirim (walau server menolaknya), widget
    // harus di-reset agar attempt berikutnya mint token baru — kalau tidak, retry
    // selamanya kirim token hangus dan gagal "kedaluwarsa".
    function resetTurnstile() {
      try { if (window.turnstile) window.turnstile.reset(); } catch (e) {}
      const el = document.querySelector('[name="cf-turnstile-response"]');
      if (el) el.value = '';
    }

    async function handleSendOtp() {
      const email = document.getElementById('otpEmailInput').value.trim();
      if (!email) return bbToast('Email wajib diisi!', 'warning');

      const turnstileToken = getTurnstileToken('turnstileOtpWidget');
      const btn = document.getElementById('btnSendOtp');
      btn.disabled = true;
      btn.querySelector('span').textContent = 'Mengirim OTP...';

      try {
        const res = await fetch('/api/auth/send-otp', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ email, turnstile_token: turnstileToken })
        });
        const data = await res.json();
        if (!res.ok) throw new Error(data.error || 'Gagal mengirim kode OTP');
        
        document.getElementById('otpSentEmail').textContent = email;
        document.getElementById('otpStep1').style.display = 'none';
        document.getElementById('otpStep2').style.display = 'block';
        bbToast(data.message || 'Kode OTP berhasil dikirim!', 'success');
        // token sudah terpakai untuk kirim OTP → minta token baru untuk langkah verifikasi
        try { if (window.turnstile) window.turnstile.reset('#turnstileOtpWidget'); } catch (e) {}
      } catch (err) {
        resetTurnstile();
        bbToast(err.message || 'Terjadi kesalahan.', 'error');
      } finally {
        btn.disabled = false;
        btn.querySelector('span').textContent = 'Kirim Kode OTP';
      }
    }

    async function handleVerifyOtp() {
      const email = document.getElementById('otpEmailInput').value.trim();
      const otp = document.getElementById('otpCodeInput').value.trim();
      if (!otp || otp.length !== 6) return bbToast('Masukkan 6 digit kode OTP!', 'warning');

      const btn = document.getElementById('btnVerifyOtp');
      btn.disabled = true;
      btn.querySelector('span').textContent = 'Memverifikasi...';

      // Verifikasi langsung. Jika widget tersembunyi tidak punya token, server hanya
      // menerima request dari browser yang memegang cookie flow HttpOnly hasil kirim OTP.
      const turnstileToken = getTurnstileToken('turnstileOtpWidget');
      const payload = { email, otp, turnstile_token: turnstileToken };
      if (pendingActivationPassword) payload.new_password = pendingActivationPassword;

      try {
        const res = await fetch('/api/auth/verify-otp', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(payload)
        });
        const data = await res.json();
        if (!res.ok) throw new Error(data.error || 'Kode OTP salah');
        resetTurnstile();
        pendingActivationPassword = '';
        window.location.href = '/setelah-masuk';
      } catch (err) {
        bbToast(err.message || 'Terjadi kesalahan.', 'error');
      } finally {
        btn.disabled = false;
        btn.querySelector('span').textContent = 'Verifikasi & Masuk';
      }
    }

    async function handleAuth(e) {
      e.preventDefault();
      const email = document.getElementById('emailInput').value.trim();
      const password = document.getElementById('passwordInput').value.trim();
      const penName = document.getElementById('penNameInput').value.trim();
      const btn = document.getElementById('btnSubmit');
      btn.disabled = true;
      btn.querySelector('span').textContent = isLoginMode ? 'Memeriksa...' : 'Mendaftarkan...';
      // Tunggu singkat untuk token; jika widget benar-benar diblokir, server memakai
      // fallback berkuota ketat. Jangan membuat tombol tampak mati selama 8 detik.
      let turnstileToken = getTurnstileToken('turnstileAuthWidget') || await tungguToken('turnstileAuthWidget', 2500);
      const endpoint = isLoginMode ? '/api/auth/login' : '/api/auth/register';

      try {
        const payload = isLoginMode
          ? { email, password, turnstile_token: turnstileToken }
          : { email, password, pen_name: penName, turnstile_token: turnstileToken };

        const res = await fetch(endpoint, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(payload)
        });
        const data = await res.json();
        if (!res.ok) throw new Error(data.error || 'Terjadi kesalahan saat masuk');

        // Pendaftaran kini butuh bukti kepemilikan email dulu (Strix #23):
        // kode sudah dikirim server, langsung minta 6 digitnya.
        if (data.need_otp) {
          pendingActivationPassword = isLoginMode ? '' : password;
          toggleOtpCard(true);
          document.getElementById('otpSentEmail').textContent = data.email || email;
          document.getElementById('otpStep1').style.display = 'none';
          document.getElementById('otpStep2').style.display = 'block';
          bbToast(data.message || 'Kami sudah mengirim kode verifikasi ke emailmu.', 'success');
          return;
        }

        window.location.href = '/setelah-masuk';
      } catch (err) {
        resetTurnstile();
        bbToast(err.message || 'Terjadi kesalahan.', 'error');
      } finally {
        btn.disabled = false;
        btn.querySelector('span').textContent = isLoginMode ? 'Masuk' : 'Daftar Pustaka';
      }
    }
  </script>
  ${NOTIFY_HTML}
</body>
</html>`;
}
